css:
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

table, td, th {
    box-sizing: border-box;
}

body {
    margin: 0;
    padding: 0;
}

.pcontainer {
    width: 100%;
    max-width: 210mm;
    margin: 0 auto;
    padding: 10mm;
    background: white;
    font-family: Arial, Helvetica, sans-serif;
    color: #000;
    font-size: 11px;
    line-height: 1.4;
    page-break-inside: avoid;
}

/* Header */
.header {
    width: 100%;
    padding-bottom: 8px;
    border-bottom: 2px solid #333;
    margin-bottom: 10px;
    border-collapse: collapse;
}

.header td {
    vertical-align: middle;
    padding: 5px;
}

.header td:first-child {
    width: 15%;
    text-align: left;
}

.header td:nth-child(2) {
    width: 70%;
    text-align: center;
}

.header td:last-child {
    width: 120px;
}

.header img {
    width: 110px;
    height: auto;
    max-height: 90px;
    display: block;
}

/* Employee Details */
.emp-details {
    padding: 8px 0;
    border-bottom: 1px solid #333;
    margin-bottom: 10px;
}

.section-title {
    font-size: 12px;
    font-weight: bold;
    margin-bottom: 5px;
}

.emp-details table {
    width: 100%;
    font-size: 11px;
    line-height: 1.5;
    border-collapse: collapse;
}

.emp-details td {
    padding: 3px 5px 3px 0;
    vertical-align: top;
}

.cell-header-title {
    width: 22%;
    font-weight: normal;
}

.cell-header-detail {
    width: 28%;
    font-weight: normal;
}

/* Payslip Info */
.payslip-section {
    padding: 8px 0;
    margin-bottom: 10px;
}

.payslip-info {
    font-size: 12px;
    font-weight: bold;
    margin-bottom: 5px;
}

.payslip-details table {
    width: 70%;
    font-size: 11px;
    line-height: 1.5;
    border-collapse: collapse;
}

.payslip-details td {
    padding: 3px 5px 3px 0;
}

.payslip-label {
    width: 70%;
}

/* Salary Tables - SINGLE COMBINED TABLE */
.salary-details {
    margin: 10px 0;
    page-break-inside: avoid;
}

.combined-salary-table {
    width: 100%;
    border: 1px solid #333;
    border-collapse: collapse;
    font-size: 10px;
    line-height: 1.4;
    table-layout: fixed;
}

.combined-salary-table thead th {
    font-weight: bold;
    background: #ffffff;
    border: 1px solid #333;
    padding: 5px;
    text-align: center;
}

.combined-salary-table .table-header-left,
.combined-salary-table .table-header-right {
    font-size: 12px;
    padding: 6px;
}

.combined-salary-table td,
.combined-salary-table th {
    padding: 4px 5px;
    border: 1px solid #333;
    vertical-align: top;
    background: white;
}

/* Column widths - apply to td:nth-child */
.combined-salary-table td:nth-child(1),
.combined-salary-table th:nth-child(1),
.combined-salary-table td:nth-child(4),
.combined-salary-table th:nth-child(4) {
    width: 35%;
    text-align: left;
}

.combined-salary-table td:nth-child(2),
.combined-salary-table th:nth-child(2),
.combined-salary-table td:nth-child(5),
.combined-salary-table th:nth-child(5) {
    width: 8%;
    text-align: center;
}

.combined-salary-table td:nth-child(3),
.combined-salary-table th:nth-child(3),
.combined-salary-table td:nth-child(6),
.combined-salary-table th:nth-child(6) {
    width: 7%;
    text-align: right;
}

.combined-salary-table .text-center {
    text-align: center;
}

.combined-salary-table .text-right {
    text-align: right;
}

/* Summary */
.total-table {
    width: 50%;
    margin: 15px 0;
}

.total-table table {
    width: 100%;
    border-collapse: collapse;
}

.total-table td {
    padding: 4px 10px 4px 0;
    font-size: 11px;
    line-height: 1.5;
}

.total-table td:last-child {
    text-align: right;
    white-space: nowrap;
}

.total-table tr:last-child td {
    font-weight: bold;
    padding-top: 8px;
}

/* Contributions */
.col-120 {
    width: 100%;
    padding-top: 10px;
    border-top: 1px solid #333;
    margin-top: 15px;
}

.col-60 {
    width: 50%;
}

.col-60 h3 {
    text-align: center;
    padding: 5px;
    margin: 0 0 -1px 0;
    font-size: 12px;
    border: 1px solid #333;
    border-bottom: none;
    background: white;
    font-weight: bold;
}

.contributions-table {
    width: 100%;
    border: 1px solid #333;
    border-collapse: collapse;
    font-size: 10px;
    line-height: 1.2;
}

.contributions-table thead td {
    font-weight: bold;
    background: #ffffff;
    border: 1px solid #333;
    padding: 3px;
}

.contributions-table td {
    padding: 4px 5px;
    border: 1px solid #333;
    vertical-align: top;
    background: white;
}

.contributions-table td:first-child {
    width: 70%;
    text-align: left;
}

.contributions-table td:last-child {
    width: 30%;
    text-align: right;
}

.contributions-table tr.total-row td {
    font-weight: bold;
    background: #ffffff;
}

/* Footer */
.footer-msg {
    text-align: center;
    padding: 10px 0;
    font-size: 10px;
    margin-top: 15px;
    color: #666;
}

/* Print Styles */
@media print {
    * {
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    body {
        margin: 0;
        padding: 0;
    }

    .pcontainer {
        width: 100%;
        max-width: none;
        margin: 0;
        padding: 8mm;
        font-size: 9px;
        page-break-after: avoid;
        page-break-before: avoid;
    }

    .header {
        page-break-after: avoid;
        page-break-inside: avoid;
    }

    .header img {
        width: 100px;
        max-height: 80px;
    }

    .combined-salary-table {
        font-size: 9px;
        page-break-inside: avoid;
    }

    .emp-details,
    .payslip-section {
        page-break-after: avoid;
        page-break-inside: avoid;
    }

    .salary-details {
        page-break-inside: avoid;
        display: table !important;
        table-layout: fixed !important;
    }

    .col-100 {
        page-break-inside: avoid;
        display: table-cell !important;
        width: 50% !important;
    }

    .sal-comp-table,
    .contributions-table {
        page-break-inside: auto;
    }

    .sal-comp-table thead,
    .contributions-table thead {
        page-break-after: avoid;
    }

    .sal-comp-table tr,
    .contributions-table tr {
        page-break-inside: avoid;
        page-break-after: auto;
    }

    .total-table {
        page-break-inside: avoid;
        page-break-before: avoid;
    }

    .col-120 {
        page-break-inside: avoid;
        page-break-before: avoid;
    }

    /* Force borders to print */
    .sal-comp-table td,
    .contributions-table td {
        border: 1px solid #333 !important;
    }
}

/* Mobile Responsive */
@media (max-width: 768px) {
    .salary-details {
        display: block;
    }

    .col-100 {
        display: block;
        width: 100%;
        margin-bottom: 15px;
    }

    .header {
        display: block;
    }

    .header > div {
        display: block;
        text-align: center;
        margin: 10px 0;
    }
}

/* Salary Tables - Two Side-by-Side Tables */
.salary-details {
    display: table;
    width: 100%;
    margin: 10px 0;
    page-break-inside: avoid;
}

.col-100 {
    display: table-cell;
    width: 50%;
    vertical-align: top;
    padding: 0 5px;
}

.col-100:first-child {
    padding-left: 0;
}

.col-100:last-child {
    padding-right: 0;
}

.sal-comp-table {
    width: 100%;
    border: 1px solid #333;
    border-collapse: collapse;
    font-size: 10px;
    line-height: 1.2;
}

.sal-comp-table thead th {
    font-weight: bold;
    background: #ffffff;
    border: 1px solid #333;
    padding: 3px 5px;
    text-align: center;
}

.sal-comp-table .table-header-left,
.sal-comp-table .table-header-right {
    font-size: 12px;
    padding: 4px;
}

.sal-comp-table td,
.sal-comp-table th {
    padding: 2px 4px;
    border: 1px solid #333;
    vertical-align: top;
    background: white;
}

.sal-comp-table td:first-child {
    width: 60%;
    text-align: left;
}

.sal-comp-table td:nth-child(2) {
    width: 15%;
    text-align: center;
}

.sal-comp-table td:nth-child(3) {
    width: 25%;
    text-align: right;
}
